import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address newOwner = address(0x123);
        address nonAdmin = address(0x456);
        // Transfer ownership to newOwner
        vm.prank(address(this)); // admin is contract deployer (address(this) in setUp)
        c.setOwner(newOwner);
        // Now nonAdmin tries to call setOwner; should fail (only admin)
        vm.prank(nonAdmin);
        bool ok;
        try c.setOwner(address(0x789)) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: revert (ok == false); buggy: no revert (ok == true)
        assertTrue(!ok);
    }
}

