import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);
        // The deployer (this test contract) becomes admin. We'll set owner to alice via admin.
        // But admin is the deployer, so we can call setOwner directly as admin.
        c.setOwner(alice);
        // Now owner is alice.
        // Now impersonate bob (not admin). We'll use try/catch because the second version reverts.
        vm.prank(bob);
        bool ok;
        try c.setOwner(bob) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference version, the call succeeds (ok = true) and owner becomes bob.
        // In the buggy version, the call reverts (ok = false) and owner remains alice.
        // We assert that the call succeeded AND the owner is bob.
        assertTrue(ok && c.owner() == bob);
    }
}

